import test from 'node:test';import {createRequire} from 'node:module';import {fileURLToPath} from 'node:url';import path from 'node:path';import assert from 'node:assert/strict';
import {refsFromManifest,validateUiDiagnostic,captureUiDiagnostic,waitUnitClientReady,canonicalActionPath,flightResponseDiagnostic,blockedRouteFault,firstRouteFault,assertUnitDispatchReady,validateSettingsDenial,probeSettingsDenial,classifyUnitRequest,parseFlightAck,ownUnitIdFromFlight,validatePrivateHandoff,materialWireArgs,ORIGIN} from './warehouse-units-stage-browser.mjs';
const refs={add:'a'.repeat(42),rename:'b'.repeat(42),delete:'c'.repeat(42),material:'d'.repeat(42)},scope={origin:ORIGIN,refs};

const runId='80502171-fcf9-4189-a3f8-c8a77e94efad',revision='a'.repeat(40);
async function publicRefs(){const {projectActionReferences,sign,ACTION_CONTRACTS,AMBIENT_CONTRACT}=await import('./warehouse-units-stage-fixtures.mjs'),raw={node:{},encryptionKey:'PRIVATE-DO-NOT-PROJECT'};for(const c of ACTION_CONTRACTS)raw.node[refs[c.key]]={exportedName:c.name,filename:c.filename,workers:{[c.worker]:{moduleId:'12345',async:false}},layer:{[c.worker]:'action-browser'}};raw.node['e'.repeat(42)]={exportedName:AMBIENT_CONTRACT.name,filename:AMBIENT_CONTRACT.filename,workers:Object.fromEntries(AMBIENT_CONTRACT.workers.map(w=>[w,{moduleId:'12345',async:false}])),layer:Object.fromEntries(AMBIENT_CONTRACT.workers.map(w=>[w,'action-browser']))};return sign(projectActionReferences(raw,{authorized:true,runId,revision},'b'.repeat(64)),'test-only-key');}
test('four action IDs come only from the signed PRE-bound manifest descriptors',async()=>{const actionReferences=await publicRefs(),pre={runId,revision,actionReferences};assert.deepEqual(refsFromManifest(actionReferences,pre),refs);for(const patch of [{revision:'c'.repeat(40)},{runId:'80502171-fcf9-4189-a3f8-c8a77e94efae'},{manifestSha256:'c'.repeat(64)},{actions:actionReferences.actions.slice(0,3)},{encryptionKey:'private'}])assert.throws(()=>refsFromManifest({...actionReferences,...patch},pre));const changed=structuredClone(actionReferences);changed.actions[0].id='e'.repeat(42);assert.throws(()=>refsFromManifest(changed,pre));});

test('only exact current own action/args on approved warehouse routes are sent',()=>{const expected={kind:'unit-add',path:'/settings/warehouse-units',ref:refs.add,args:[{name:'QA own B'}]},request={url:ORIGIN+'/settings/warehouse-units',method:'POST',headers:{'next-action':refs.add,'content-type':'text/plain;charset=UTF-8'},body:JSON.stringify(expected.args)};assert.equal(classifyUnitRequest(request,scope,expected).kind,'action');for(const patch of [{url:'https://prod.example/warehouse/items'},{url:ORIGIN+'/my'},{body:'[{"name":"other"}]'},{headers:{'next-action':refs.delete}},{method:'PUT'}])assert.equal(classifyUnitRequest({...request,...patch},scope,expected).kind,'deny');assert.equal(classifyUnitRequest(request,scope,null).kind,'deny');assert.equal(classifyUnitRequest({url:ORIGIN+'/_next/static/chunks/x.js',method:'GET',headers:{}},scope,null).kind,'read');assert.equal(classifyUnitRequest({url:ORIGIN+'/api/auth/signout',method:'GET',headers:{}},scope,null).kind,'deny');});
test('ACK parses exact Flight ok/used/role denials without exposing raw text',()=>{assert.deepEqual(parseFlightAck(200,'0:{"ok":true}',{expect:'ok'}),{status:'ok'});assert.deepEqual(parseFlightAck(200,'1:{"ok":false,"error":"Единица используется в номенклатуре. Сначала выберите другую единицу"}',{expect:'used-denied'}),{status:'used-denied'});assert.deepEqual(parseFlightAck(302,'',{kind:'unit-rename',actorRole:'MANAGER',expect:'role-denied'},{responseUrl:ORIGIN+'/settings/warehouse-units',location:'/'}),{status:'role-denied',layer:'route'});assert.throws(()=>parseFlightAck(500,'0:E{"digest":"8373"}',{expect:'role-denied'}));for(const [status,body,expect]of [[400,'bad csrf','role-denied'],[303,'login','role-denied'],[200,'0:{"ok":false,"error":"duplicate"}','used-denied'],[500,'0:E{"digest":"8373"}','ok'],[200,'0:{"ok":true}','role-denied']])assert.throws(()=>parseFlightAck(status,body,{expect}));});
test('new unit CUID is learned only from exact own tag in bounded Flight rows',()=>{const body='0:["$",null,{"rows":[{"id":"existing","name":"real"},{"id":"ownb1","name":"QA own B"}]}]';assert.equal(ownUnitIdFromFlight(body,'QA own B'),'ownb1');assert.throws(()=>ownUnitIdFromFlight(body,'missing'));assert.throws(()=>ownUnitIdFromFlight(body+'\n1:{"id":"ownb2","name":"QA own B"}','QA own B'));});
test('private handoff requires four exact own actor roles and secure origin cookies',async()=>{const actionReferences=await publicRefs();const pre={runId:'80502171-fcf9-4189-a3f8-c8a77e94efad',revision:'a'.repeat(40),signature:'b'.repeat(64),actionReferences,actors:Object.fromEntries(['ADMIN','MANAGER','ENGINEER','DIRECTOR'].map(r=>[r,{id:'own'+r,roles:[r]}]))},profiles=Object.fromEntries(Object.entries(pre.actors).map(([role,actor])=>[role,{...actor,cookies:[{name:'authjs.session-token',value:'private',url:ORIGIN,httpOnly:true,secure:true,sameSite:'Lax'}]}])),input={authorized:true,origin:ORIGIN,revision:pre.revision,identity:{hostname:'crm-staging',revision:pre.revision},pre,actionReferences,profiles};assert.doesNotThrow(()=>validatePrivateHandoff(input));assert.throws(()=>validatePrivateHandoff({...input,profiles:{...profiles,ADMIN:{...profiles.ADMIN,roles:['DIRECTOR']}}}));assert.throws(()=>validatePrivateHandoff({...input,origin:'https://prod.example'}));assert.throws(()=>validatePrivateHandoff({...input,profiles:{...profiles,ENGINEER:{...profiles.ENGINEER,cookies:[{...profiles.ENGINEER.cookies[0],url:'https://prod.example'}]}}}));});

test('prefetch is aborted without opening unrelated screens or failing the run',()=>{assert.equal(classifyUnitRequest({url:ORIGIN+'/projects',method:'GET',headers:{'next-router-prefetch':'1'}},scope,null).kind,'abort-prefetch');assert.equal(classifyUnitRequest({url:ORIGIN+'/products',method:'GET',headers:{purpose:'prefetch'}},scope,null).kind,'abort-prefetch');assert.equal(classifyUnitRequest({url:ORIGIN+'/projects',method:'GET',headers:{}},scope,null).kind,'deny');});

test('actual installed Flight encoder preserves optional fields as $undefined',async()=>{const require=createRequire(import.meta.url),next=path.dirname(require.resolve('next/package.json'));const originalWebpack=globalThis.__webpack_require__,originalLoader=globalThis.__webpack_chunk_load__;try{globalThis.__webpack_require__=Object.assign(()=>{throw Error('NO_MODULE_LOAD');},{u:()=>''});globalThis.__webpack_chunk_load__=()=>{throw Error('NO_CHUNK_LOAD');};const flight=require(path.join(next,'dist/compiled/react-server-dom-webpack/client.browser.js'));const pre={ids:{materialActive:'own-active'},tags:{active:'QA own active'}},args=['own-active',{name:pre.tags.active,sku:undefined,unitId:'own-unit',categoryId:undefined,minStock:3,comment:undefined}],encoded=await flight.encodeReply(args);assert.deepEqual(JSON.parse(encoded),materialWireArgs(pre,'active','own-unit'));}finally{globalThis.__webpack_require__=originalWebpack;globalThis.__webpack_chunk_load__=originalLoader;}});

test('settings denial probe never follows redirects and refuses login/products/external or false success',async()=>{for(const role of ['MANAGER','ENGINEER','DIRECTOR'])for(const status of [302,307,308]){let seen;const page={request:{async get(url,options){seen={url,options};return {status:()=>status,url:()=>ORIGIN+'/settings/warehouse-units',headers:()=>({location:ORIGIN+'/'})};}}};assert.equal((await probeSettingsDenial(page,role)).followed,false);assert.deepEqual(seen,{url:ORIGIN+'/settings/warehouse-units',options:{maxRedirects:0,maxRetries:0}});}const valid={role:'ENGINEER',status:302,responseUrl:ORIGIN+'/settings/warehouse-units',location:'/'};for(const patch of [{role:'ADMIN'},{status:200},{status:401},{status:500},{responseUrl:ORIGIN+'/products'},{location:ORIGIN+'/products'},{location:'/login'},{location:'/settings'},{location:'/?next=products'},{location:'/#fragment'},{location:'https://other.invalid/'},{location:'//staging-crm.peromebel.by/'},{location:'/../'}])assert.throws(()=>validateSettingsDenial({...valid,...patch}));assert.equal(classifyUnitRequest({url:ORIGIN+'/products',method:'GET',headers:{}},scope,null).kind,'deny');});
test('actual app authorization denies unit settings to root before ENGINEER home products navigation',async()=>{const require=createRequire(import.meta.url),{build}=createRequire(require.resolve('tsx/package.json'))('esbuild'),web=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');const built=await build({entryPoints:[path.join(web,'src/auth.config.ts')],bundle:true,write:false,platform:'node',format:'esm',target:'node22',minify:true,tsconfig:path.join(web,'tsconfig.json'),logLevel:'silent'}),policy=await import('data:text/javascript;base64,'+Buffer.from(built.outputFiles[0].contents).toString('base64'));for(const role of ['MANAGER','ENGINEER','DIRECTOR']){const response=policy.authConfig.callbacks.authorized({auth:{user:{roles:[role]}},request:{nextUrl:new URL(ORIGIN+'/settings/warehouse-units')}});assert.equal(response.status,302);assert.equal(response.headers.get('location'),ORIGIN+'/');assert.equal(validateSettingsDenial({role,status:response.status,responseUrl:ORIGIN+'/settings/warehouse-units',location:response.headers.get('location')}).denied,true);}const allowed=policy.authConfig.callbacks.authorized({auth:{user:{roles:['ADMIN']}},request:{nextUrl:new URL(ORIGIN+'/settings/warehouse-units')}});assert.equal(allowed,true);const follow=policy.authConfig.callbacks.authorized({auth:{user:{roles:['ENGINEER']}},request:{nextUrl:new URL(ORIGIN+'/')}});assert.equal(follow.status,302);assert.equal(follow.headers.get('location'),ORIGIN+'/products');});

test('first blocked request retains specific finite code through later faults and dispatch guard',()=>{const first=blockedRouteFault({code:'ACTION_SCOPE'},{url:ORIGIN+'/warehouse/items?private=do-not-print',method:'POST',headers:{'next-action':'e'.repeat(42),cookie:'do-not-print'},body:'do-not-print'},refs);assert.equal(first.message,'UNIT110_BLOCKED_ACTION_SCOPE_POST_WAREHOUSE_ITEMS_UNKNOWN');assert.equal(first.message.includes('do-not-print'),false);assert.equal(first.message.includes('e'.repeat(42)),false);const later=blockedRouteFault({code:'GET_SCOPE'},{url:ORIGIN+'/private/customer/path',method:'GET'},refs);assert.equal(firstRouteFault(first,later),first);assert.throws(()=>assertUnitDispatchReady(null,first),e=>e===first);assert.throws(()=>assertUnitDispatchReady({},null));assert.doesNotThrow(()=>assertUnitDispatchReady(null,null));const known=blockedRouteFault({code:'EXACT_OWN_ARGUMENTS'},{url:ORIGIN+'/settings/warehouse-units',method:'POST',headers:{'next-action':refs.add}},refs);assert.equal(known.message,'UNIT110_BLOCKED_EXACT_OWN_ARGUMENTS_POST_UNIT_SETTINGS_UNIT_ADD');});

test('only signed exact getBellData ID+JSON[] on fixed owned page is aborted without dispatch',async()=>{const projected=await publicRefs(),ambient=projected.ambient[0],binding={...scope,ambient},request={url:ORIGIN+'/warehouse/items',method:'POST',headers:{'next-action':ambient.id,'content-type':'text/plain;charset=UTF-8'},body:'[]'};assert.equal(classifyUnitRequest(request,binding,null).kind,'abort-ambient');assert.equal(classifyUnitRequest({...request,url:ORIGIN+'/settings/warehouse-units'},binding,{ref:refs.add,args:[{}]}).kind,'abort-ambient');for(const patch of [{url:ORIGIN+'/products'},{url:ORIGIN+'/warehouse/items?unknown=1'},{body:'["owned-or-real"]'},{body:'{}'},{body:'not-json'},{method:'PUT'},{headers:{'next-action':'f'.repeat(42),'content-type':'text/plain'}},{headers:{'next-action':refs.delete,'content-type':'text/plain'}}])assert.equal(classifyUnitRequest({...request,...patch},binding,null).kind,'deny');assert.equal(classifyUnitRequest(request,{...scope},null).kind,'deny');assert.equal(classifyUnitRequest(request,{...scope,ambient:{...ambient,name:'markAllRead'}},null).kind,'deny');assert.equal(classifyUnitRequest(request,{...scope,ambient:{...ambient,filename:'server/other.ts'}},null).kind,'deny');});

test('unit RPC uses signed canonical settings worker and material RPC own warehouse worker',async()=>{const references=await publicRefs();for(const kind of ['unit-add','unit-rename','unit-delete'])assert.equal(canonicalActionPath(kind,references),'/settings/warehouse-units');assert.equal(canonicalActionPath('material-swap',references),'/warehouse/items');assert.throws(()=>canonicalActionPath('preference',references));const bad=structuredClone(references);bad.actions[0].workers=['app/(app)/warehouse/items/page'];assert.throws(()=>canonicalActionPath('unit-add',bad));const require=createRequire(import.meta.url),next=path.dirname(require.resolve('next/package.json')),actual=require(path.join(next,'dist/server/app-render/action-utils.js'));const node=Object.fromEntries(references.actions.map(a=>[a.id,{workers:Object.fromEntries(a.workers.map(w=>[w,{moduleId:'123',async:false}]))}]));assert.equal(actual.selectWorkerForForwarding(refs.rename,'/(app)/warehouse/items/page',{node,edge:{}}),'/settings/warehouse-units');assert.equal(actual.selectWorkerForForwarding(refs.rename,'/(app)/settings/warehouse-units/page',{node,edge:{}}),undefined);assert.equal(actual.selectWorkerForForwarding(refs.material,'/(app)/warehouse/items/page',{node,edge:{}}),undefined);const op={kind:'unit-rename',path:'/settings/warehouse-units',ref:refs.rename,args:['own',{name:'own'}]},request={url:ORIGIN+'/settings/warehouse-units',method:'POST',headers:{'next-action':refs.rename,'content-type':'text/plain'},body:JSON.stringify(op.args)};assert.equal(classifyUnitRequest(request,scope,op).kind,'action');assert.equal(classifyUnitRequest({...request,url:ORIGIN+'/warehouse/items'},scope,op).kind,'deny');});
test('nonADMIN endpoint ACK accepts only canonical manual redirect, never opaque Flight/error/JSON',()=>{const intent={kind:'unit-rename',actorRole:'MANAGER',expect:'role-denied'};for(const status of [302,307,308])assert.deepEqual(parseFlightAck(status,'',intent,{responseUrl:ORIGIN+'/settings/warehouse-units',location:ORIGIN+'/'}),{status:'role-denied',layer:'route'});for(const [status,body]of [[200,'{}'],[200,'0:{"a":"$@1"}\n1:E{"digest":"8373"}'],[500,'0:{"a":"$@1"}\n1:E{"digest":"8373"}'],[403,'denied'],[401,'login'],[200,'0:{"ok":false,"error":"Недостаточно прав"}']])assert.throws(()=>parseFlightAck(status,body,intent),e=>/^UNIT110_ROLE_REPLY_/.test(e.message));assert.throws(()=>parseFlightAck(302,'',{...intent,actorRole:'ADMIN'},{responseUrl:ORIGIN+'/settings/warehouse-units',location:'/'}));assert.throws(()=>parseFlightAck(302,'',intent,{responseUrl:ORIGIN+'/warehouse/items',location:'/'}));assert.throws(()=>parseFlightAck(302,'',intent,{responseUrl:ORIGIN+'/settings/warehouse-units',location:'/login'}));});
test('bounded response diagnosis exposes only safe enums/counts and never body/digest/message/header values',()=>{const sample='0:{"a":"$@1"}\n1:E{"digest":"123456","message":"PRIVATE BODY VALUE","stack":["PRIVATE TRACE"],"env":"PRIVATE ENV"}';const diagnostic=flightResponseDiagnostic(200,sample,{location:ORIGIN+'/private/user/id'});assert.equal(diagnostic.statusBucket,'HTTP200');assert.equal(diagnostic.bodyKind,'FLIGHT');assert.equal(diagnostic.errorCount,1);assert.equal(diagnostic.errorDigestShape,'NUMERIC');assert.equal(diagnostic.errorShapeValid,true);const output=JSON.stringify(diagnostic);for(const value of ['123456','PRIVATE BODY','PRIVATE TRACE','PRIVATE ENV','/private/user'])assert.equal(output.includes(value),false);assert.equal(flightResponseDiagnostic(200,'{}').bodyKind,'EMPTY_OBJECT');assert.equal(flightResponseDiagnostic(500,'1:E{"digest":"opaque","unknown":"secret"}').errorShapeValid,false);assert.equal(flightResponseDiagnostic(500,Array.from({length:20},(_,i)=>i.toString(16)+':E{"digest":"1"}').join('\n')).errorCount,16);assert.equal(flightResponseDiagnostic(500,Array.from({length:20},(_,i)=>i.toString(16)+':E{"digest":"1"}').join('\n')).tooManyErrors,true);});

test('UI diagnostic snapshots only fixed booleans/counts and client-ready barrier requires closed modal+enabled control',async()=>{const root={getByRole(role,options){return {count:async()=>role==='dialog'?1:options.name==='Сохранение…'?1:1,isVisible:async()=>options.name==='Новая единица'||options.name.startsWith('Переименовать единицу '),isEnabled:async()=>false};}},d=await captureUiDiagnostic(root,{step:'RENAME_OPEN',targetName:'PRIVATE OWN LABEL',errorName:'TimeoutError'});assert.equal(d.step,'RENAME_OPEN');assert.equal(d.errorKind,'TIMEOUT');assert.equal(d.createModalVisible,true);assert.equal(d.submitBusyCount,1);assert.equal(d.ownButtonEnabled,false);assert.equal(JSON.stringify(d).includes('PRIVATE'),false);assert.throws(()=>validateUiDiagnostic({...d,message:'private'}));assert.throws(()=>validateUiDiagnostic({...d,ownButtonCount:99}));const broken=await captureUiDiagnostic({getByRole(){throw Error('private raw exception');}},{step:'CREATE_READY',errorName:'Error'});assert.equal(broken.snapshotFailed,true);assert.equal(JSON.stringify(broken).includes('private'),false);const counts=[];const page={getByRole(role,options){counts.push({role,name:options.name});return {all:async()=>[],count:async()=>0,isVisible:async()=>false,isEnabled:async()=>true};}};await waitUnitClientReady(page,'Новая единица');assert.deepEqual(counts,[{role:'dialog',name:'Новая единица'},{role:'button',name:'Добавить единицу'}]);});
